const item = $input.item;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = buf.toString('base64');
const srcBin = (item.binary && item.binary.data) ? item.binary.data : null;
const mime = (srcBin && srcBin.mimeType) ? srcBin.mimeType : 'image/jpeg';

let msgId = 'unknown';
try { msgId = $('Telegram Receipt Trigger').item.json.message.message_id ?? 'unknown'; } catch (e) {}

return {
  json: {
    intake_channel: 'telegram',
    source_ref: 'tg:' + msgId,
    openai_user_content: [
      { type: 'text', text: 'Extract the receipt fields as JSON.' },
      { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + b64 } }
    ]
  },
  binary: srcBin ? { receipt_file: srcBin } : {}
};

// One item per email attachment, binary standardised to source_file.
const out = [];
for (const item of $input.all()) {
  try {
    const j = item.json || {};
    const bins = item.binary || {};
    const messageId = j.id || j.messageId || (j.headers && j.headers['message-id']) || 'unknown';
    let idx = 0;
    for (const key of Object.keys(bins)) {
      if (key.indexOf('attachment_') !== 0) continue;
      const b = bins[key];
      out.push({
        json: {
          messageId: String(messageId),
          attachment_index: idx,
          filename: b.fileName || ('attachment_' + idx),
          mimeType: b.mimeType || 'application/octet-stream'
        },
        binary: { source_file: b }
      });
      idx++;
    }
  } catch (e) {
    throw new Error('Split Email Attachments failed: ' + e.message);
  }
}
return out;

// Run Once for All Items.
// One candidate per PDF page using the text layer. Pages split on form-feed.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const text = j.text || '';
  const srcBin = (item.binary && item.binary.source_file) ? item.binary.source_file : null;

  let pages = text.split('\f').map(p => p.trim()).filter(p => p.length > 0);
  if (pages.length === 0) pages = [''];

  pages.forEach((p, i) => {
    out.push({
      json: {
        messageId: j.messageId ?? null,
        attachment_index: j.attachment_index ?? 0,
        page_index: i,
        page_text: p,
        filename: j.filename ?? null,
        mimeType: 'application/pdf'
      },
      binary: srcBin ? { source_file: srcBin } : {}
    });
  });
}
return out;

// Normalise an image attachment OR a PDF page into the common candidate shape.
try {
  const j = $json;
  const isPdf = (j.page_text !== undefined) || (j.mimeType === 'application/pdf');
  const messageId = j.messageId || 'unknown';
  const attIdx = (j.attachment_index !== undefined) ? j.attachment_index : 0;
  const pageIdx = (j.page_index !== undefined) ? j.page_index : 0;
  const sourceRef = 'em:' + messageId + ':att' + attIdx + ':page' + pageIdx;
  const bin = ($binary && $binary.source_file) ? $binary.source_file : null;
  let candidateKind, userContent, mime;
  if (isPdf) {
    candidateKind = 'pdf_text';
    mime = 'application/pdf';
    const pageText = j.page_text || '';
    userContent = [ { type: 'text', text: 'Extract the receipt fields as JSON from this receipt text:\n' + pageText } ];
  } else {
    candidateKind = 'image';
    mime = j.mimeType || (bin && bin.mimeType) || 'image/jpeg';
    if (!bin) { throw new Error('Email image binary missing on property source_file'); }
    const dataUri = 'data:' + mime + ';base64,' + bin.data;
    userContent = [ { type: 'text', text: 'Extract the receipt fields as JSON.' }, { type: 'image_url', image_url: { url: dataUri } } ];
  }
  return {
    json: {
      intake_channel: 'email',
      source_ref: sourceRef,
      candidate_kind: candidateKind,
      mime_type: mime,
      openai_user_content: userContent
    },
    binary: bin ? { receipt_file: bin } : {}
  };
} catch (e) {
  throw new Error('Normalise Email Intake failed: ' + e.message);
}

// Generate one v4 workflow_run_id per execution (Math.random, never $execution.id, never $crypto).
function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const runId = uuidv4();
return $input.all().map(function (it) {
  return { json: Object.assign({}, it.json, { workflow_run_id: runId }), binary: it.binary };
});

// Parse the vision JSON, mask card digits (regex, not hashing), type fields, amounts to integer minor units, compute vendor_norm and is_foreign_currency, and prebuild the QBO query window.
try {
  const raw = ($json.choices && $json.choices[0] && $json.choices[0].message) ? $json.choices[0].message.content : '{}';
  let ex;
  try { ex = JSON.parse(raw); } catch (_) { ex = {}; }
  const mask = function (s) {
    if (s === null || s === undefined) return s;
    return String(s).replace(/(?:\d[ -]*?){12,19}/g, function (m) { const d = m.replace(/\D/g, ''); return '*'.repeat(Math.max(0, d.length - 4)) + d.slice(-4); });
  };
  const toMinor = function (v) { if (v === null || v === undefined || v === '') return null; const n = Math.round(Number(v) * 100); return Number.isFinite(n) ? n : null; };
  const vendorRaw = ex.vendor ? mask(ex.vendor) : null;
  const vendorNorm = vendorRaw ? String(vendorRaw).toLowerCase().replace(/[^a-z0-9]/g, '') : null;
  const currency = (ex.currency_code || 'USD').toString().toUpperCase().slice(0, 3);
  let qboQuery = null;
  if (ex.date) {
    const base = new Date(ex.date + 'T00:00:00Z');
    if (!isNaN(base.getTime())) {
      const s = new Date(base.getTime() - 1 * 86400000).toISOString().slice(0, 10);
      const e = new Date(base.getTime() + 5 * 86400000).toISOString().slice(0, 10);
      qboQuery = "select * from Purchase where TxnDate >= '" + s + "' and TxnDate <= '" + e + "' maxresults 200";
    }
  }
  return {
    json: {
      vendor_raw: vendorRaw,
      vendor_norm: vendorNorm,
      receipt_date: ex.date || null,
      currency_code: currency,
      is_foreign_currency: currency !== 'USD',
      total_minor: toMinor(ex.total),
      tax_minor: toMinor(ex.tax),
      line_items_json: Array.isArray(ex.line_items) ? ex.line_items : [],
      payment_method_masked: ex.payment_method ? mask(ex.payment_method) : null,
      extraction_confidence: (ex.overall_confidence !== undefined && ex.overall_confidence !== null) ? Number(ex.overall_confidence) : null,
      field_confidence_json: ex.field_confidence || {},
      qbo_query: qboQuery
    }
  };
} catch (e) {
  throw new Error('Normalise & Mask Extraction failed: ' + e.message);
}

// Line items + tax reconcile to total within 2 cents (integer minor units), date sanity, confidence threshold. Precompute the review reason and detail; foreign currency takes precedence.
try {
  const r = $('Normalise & Mask Extraction').item.json;
  const reasons = [];
  let passed = true;
  const items = Array.isArray(r.line_items_json) ? r.line_items_json : [];
  const sumItems = items.reduce(function (a, li) { const c = Math.round(Number(li.amount) * 100); return a + (Number.isFinite(c) ? c : 0); }, 0);
  const tax = r.tax_minor || 0;
  const total = r.total_minor;
  if (total === null || total === undefined) { passed = false; reasons.push('missing_total'); }
  let reconcileOk = true;
  if (total !== null && total !== undefined && items.length > 0) {
    reconcileOk = Math.abs((sumItems + tax) - total) <= 2;
    if (!reconcileOk) { passed = false; reasons.push('line_items_do_not_reconcile'); }
  }
  const now = Date.now();
  if (!r.receipt_date) { passed = false; reasons.push('missing_date'); }
  else {
    const d = new Date(r.receipt_date + 'T00:00:00Z').getTime();
    if (isNaN(d)) { passed = false; reasons.push('unparseable_date'); }
    else {
      if (d > now + 86400000) { passed = false; reasons.push('future_date'); }
      if (now - d > 3650 * 86400000) { passed = false; reasons.push('too_old'); }
    }
  }
  const CONF_THRESHOLD = 0.70;
  const conf = (r.extraction_confidence === null || r.extraction_confidence === undefined) ? 0 : Number(r.extraction_confidence);
  const lowConf = conf < CONF_THRESHOLD;
  let needsReview = false; let reviewReason = null;
  if (r.is_foreign_currency) { needsReview = true; reviewReason = 'FOREIGN_CURRENCY'; }
  else if (!passed) { needsReview = true; reviewReason = 'VALIDATION_FAILED'; }
  else if (lowConf) { needsReview = true; reviewReason = 'LOW_CONFIDENCE_EXTRACTION'; }
  return {
    json: {
      validation_passed: passed,
      failed_check: passed ? null : reasons.join(','),
      needs_review: needsReview,
      review_reason: reviewReason,
      review_detail: { reasons: reasons, sum_items_minor: sumItems, tax_minor: tax, total_minor: total, reconcile_ok: reconcileOk, extraction_confidence: conf, is_foreign_currency: r.is_foreign_currency, currency_code: r.currency_code }
    }
  };
} catch (e) {
  throw new Error('Validate failed: ' + e.message);
}

// Match Engine: client-side filter (PaymentType, holding account), two hard gates (date, amount), weighted score over qualifiers.
try {
  const r = $('Normalise & Mask Extraction').item.json;
  const resp = ($json && $json.QueryResponse) ? $json.QueryResponse : {};
  const purchases = Array.isArray(resp.Purchase) ? resp.Purchase : [];
  const HOLDING = ['uncategorized expense', 'uncategorised expense', 'ask my accountant'];
  const receiptDate = r.receipt_date ? new Date(r.receipt_date + 'T00:00:00Z').getTime() : null;
  const totalMinor = r.total_minor;
  const norm = function (s) { return (s || '').toString().toLowerCase().replace(/[^a-z0-9]/g, ''); };
  const vendorNorm = r.vendor_norm || '';
  const sim = function (a, b) { a = norm(a); b = norm(b); if (!a || !b) return 0; if (a === b) return 1; const short = a.length < b.length ? a : b; const long = a.length < b.length ? b : a; return long.indexOf(short) >= 0 ? short.length / long.length : 0; };
  const dayMs = 86400000;
  const qualifiers = [];
  for (const p of purchases) {
    const pt = (p.PaymentType || '').toString();
    if (pt !== 'CreditCard' && pt !== 'Cash') continue;
    const lines = Array.isArray(p.Line) ? p.Line : [];
    const holdingLine = lines.find(function (l) { return l.AccountBasedExpenseLineDetail && l.AccountBasedExpenseLineDetail.AccountRef && HOLDING.indexOf((l.AccountBasedExpenseLineDetail.AccountRef.name || '').toLowerCase()) >= 0; });
    if (!holdingLine) continue;
    const td = p.TxnDate ? new Date(p.TxnDate + 'T00:00:00Z').getTime() : null;
    if (td === null || receiptDate === null) continue;
    if (td < receiptDate - 1 * dayMs || td > receiptDate + 5 * dayMs) continue;
    const cand = Math.round(Number(p.TotalAmt) * 100);
    if (!Number.isFinite(cand) || totalMinor === null || totalMinor === undefined) continue;
    if (cand < totalMinor - 2) continue;
    if (cand > Math.round(totalMinor * 1.25)) continue;
    const amountExact = Math.abs(cand - totalMinor) <= 2;
    const amountScore = amountExact ? 1.0 : 0.5;
    const vendorScore = sim(vendorNorm, (p.EntityRef && p.EntityRef.name) || p.PrivateNote || '');
    const dayDiff = Math.abs(td - receiptDate) / dayMs;
    const dateScore = Math.max(0, 1 - (dayDiff / 6));
    const score = 0.55 * amountScore + 0.25 * vendorScore + 0.20 * dateScore;
    qualifiers.push({ id: p.Id, syncToken: p.SyncToken, txn: p, amountExact: amountExact, amountScore: amountScore, vendorScore: vendorScore, dateScore: dateScore, score: score });
  }
  qualifiers.sort(function (a, b) { return b.score - a.score; });
  let decision = 'NO_MATCH', matchedId = null, matchScore = null, matchedTxn = null, reviewReason = null, reviewDetail = null;
  if (qualifiers.length > 0) {
    const top = qualifiers[0];
    const second = qualifiers[1];
    const strongVendor = top.vendorScore >= 0.6;
    const tightDate = top.dateScore >= 0.66;
    const several = second && (top.score - second.score) < 0.1;
    if (top.amountExact && strongVendor && tightDate && !several) {
      decision = 'MATCHED'; matchedId = top.id; matchScore = top.score; matchedTxn = top.txn;
    } else {
      decision = 'AMBIGUOUS'; matchedId = top.id; matchScore = top.score; matchedTxn = top.txn; reviewReason = 'AMBIGUOUS_MATCH';
      reviewDetail = { topScore: top.score, candidates: qualifiers.slice(0, 3).map(function (q) { return { id: q.id, score: q.score, amountExact: q.amountExact, vendorScore: q.vendorScore, dateScore: q.dateScore }; }) };
    }
  }
  const matchBasis = { qualifier_count: qualifiers.length, decision: decision, top: qualifiers[0] ? { id: qualifiers[0].id, score: qualifiers[0].score, amount_score: qualifiers[0].amountScore, vendor_score: qualifiers[0].vendorScore, date_score: qualifiers[0].dateScore } : null };
  return {
    json: {
      match_decision: decision,
      match_status: decision === 'MATCHED' ? 'MATCHED' : (decision === 'AMBIGUOUS' ? 'REVIEW' : 'NO_MATCH'),
      matched_txn_id: matchedId,
      match_score: matchScore,
      match_basis_json: matchBasis,
      matched_txn: matchedTxn,
      review_reason: reviewReason,
      review_detail: reviewDetail
    }
  };
} catch (e) {
  throw new Error('Match Engine failed: ' + e.message);
}

