// Parse the AI categorisation. Enforce a numeric account id; anything else, or low confidence, routes to review.
try {
  const raw = ($json.choices && $json.choices[0] && $json.choices[0].message) ? $json.choices[0].message.content : '{}';
  let c;
  try { c = JSON.parse(raw); } catch (_) { c = {}; }

  const THR = 0.70;
  const conf = (c.confidence === undefined || c.confidence === null) ? 0 : Number(c.confidence);

  const rawId = (c.account_id !== undefined && c.account_id !== null) ? String(c.account_id) : null;
  const validId = (rawId && /^[0-9]+$/.test(rawId)) ? rawId : null;
  const account = validId;                       // only ever a numeric id, or null

  const needsReview = (conf < THR) || (account === null);

  return {
    json: {
      category_account: account,
      category_source: 'AI',
      category_confidence: conf,
      needs_category_review: needsReview,
      review_reason: 'AMBIGUOUS_CATEGORY',
      review_detail: { source: 'AI', suggested: c, confidence: conf }
    }
  };
} catch (e) {
  throw new Error('Parse Category failed: ' + e.message);
}

try {
  const lb = $('Per-Candidate Loop').item;
  const bin = (lb && lb.binary && lb.binary.receipt_file) ? lb.binary.receipt_file : null;
  const mime = (bin && bin.mimeType) ? bin.mimeType : 'application/pdf';
  const ext = mime.indexOf('pdf') >= 0 ? 'pdf' : (mime.indexOf('png') >= 0 ? 'png' : 'jpg');
  return {
    json: {
      category_account: $json.category_account,
      category_source: $json.category_source,
      category_confidence: $json.category_confidence,
      filename: 'receipt.' + ext,
      mimeType: mime
    },
    binary: bin ? { receipt_file: bin } : {}
  };
} catch (e) {
  throw new Error('Prepare Attachment Binary failed: ' + e.message);
}

