// Converge the matched and no-match post branches; extract QBO ids without referencing an un-run node.
try {
  const dec = $('Match Engine').item.json.match_decision;
  let purchaseId = null, attachableId = null;
  if (dec === 'MATCHED') {
    purchaseId = $('Match Engine').item.json.matched_txn_id;
    const ar = $('Attach Receipt').item.json.AttachableResponse;
    attachableId = (ar && ar[0] && ar[0].Attachable) ? ar[0].Attachable.Id : null;
  } else {
    purchaseId = ($json.Purchase && $json.Purchase.Id) ? $json.Purchase.Id : null;
  }
  const cat = $('Category Gate').item.json;
  return {
    json: {
      qbo_purchase_id: purchaseId,
      qbo_attachable_id: attachableId,
      category_account: cat.category_account,
      category_source: cat.category_source,
      category_confidence: cat.category_confidence
    }
  };
} catch (e) {
  throw new Error('Collect Post Result failed: ' + e.message);
}

