const meta = {
  AttachableRef: [
    { EntityRef: { type: "Purchase", value: $('Match Engine').item.json.matched_txn.Id } }
  ],
  FileName: ($('Prepare Attachment Binary').item.json.filename || "receipt.pdf"),
  ContentType: ($('Prepare Attachment Binary').item.json.mimeType || "application/pdf")
};

const b = Buffer.from(JSON.stringify(meta), 'utf8');

const item = $input.item;
item.binary = item.binary || {};
item.binary.meta_json = {
  data: b.toString('base64'),
  mimeType: 'application/json',
  fileName: 'metadata.json'
};
return item;

// Match extracted vendor to a QBO vendor by normalised name; carry category forward.
const want = String($('Normalise & Mask Extraction').item.json.vendor_norm || '');
const q = $json.QueryResponse;                 // Find Vendor output
const list = (q && q.Vendor) ? q.Vendor : [];
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

let vendorId = null, vendorName = null;
for (const v of list) {
  if (norm(v.DisplayName) === want) { vendorId = v.Id; vendorName = v.DisplayName; break; }
}

return {
  json: {
    category_account: $('Is Matched').item.json.category_account,
    matched_vendor_id: vendorId,
    matched_vendor_name: vendorName
  }
};

